/// `tanh_sat` = 20.0: a chart constant an operator reads, not a tree (dd_generation_root §3.9), at the float
/// type `R`, the register entry's value converted from f32, where it is exact. Emitted as a function of `R`
/// rather than a [`ChartConstants`] item: an operator's bound is one number at every float type the links are
/// evaluated at, not a per-type choice, so a type outside the kernel's two (a test's dual number) reads it too.
/// Were the conversion ever to fail, the bound would be `R`'s largest finite value, and the operator unclamped.
#[inline]
pub fn tanh_sat<R: Float>() -> R {
    let v: f32 = 20.0;
    <R as NumCast>::from(v).unwrap_or_else(R::max_value)
}
